      <SegmentedRadioGroup.Option value="light" title="Светлая тема">
        <Icon data={Sun} size={16} /> Светлая
      </SegmentedRadioGroup.Option>
      <SegmentedRadioGroup.Option value="dark" title="Тёмная тема">
        <Icon data={Moon} size={16} /> Тёмная
      </SegmentedRadioGroup.Option>
    </SegmentedRadioGroup>
  );
}
